// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/refresh", wrapper.RefreshSession)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/auth/me", wrapper.GetMe)
	router.GET(options.BaseURL+"/catalog/products", wrapper.ListProducts)
	router.GET(options.BaseURL+"/catalog/products/:slug", wrapper.GetProduct)
	router.GET(options.BaseURL+"/catalog/brands", wrapper.ListBrands)
	router.GET(options.BaseURL+"/catalog/brands/:slug", wrapper.GetBrand)
	router.GET(options.BaseURL+"/catalog/menu", wrapper.GetMenu)
	router.GET(options.BaseURL+"/delivery/zones", wrapper.ListDeliveryZones)
	router.POST(options.BaseURL+"/cart/quote", wrapper.QuoteCart)
	router.POST(options.BaseURL+"/orders", wrapper.CreateOrder)
	router.POST(options.BaseURL+"/orders/:orderId/pay", wrapper.PayOrder)
	router.GET(options.BaseURL+"/orders/:orderId/payment", wrapper.GetOrderPayment)
	router.GET(options.BaseURL+"/orders/:number/status", wrapper.GetOrderStatus)
	router.POST(options.BaseURL+"/webhooks/payments/:provider", wrapper.ReceivePaymentWebhook)
	router.GET(options.BaseURL+"/admin/brands", wrapper.AdminListBrands)
	router.POST(options.BaseURL+"/admin/brands", wrapper.AdminCreateBrand)
	router.DELETE(options.BaseURL+"/admin/brands/:brandId", wrapper.AdminDeleteBrand)
	router.GET(options.BaseURL+"/admin/brands/:brandId", wrapper.AdminGetBrand)
	router.PUT(options.BaseURL+"/admin/brands/:brandId", wrapper.AdminUpdateBrand)
	router.GET(options.BaseURL+"/admin/products", wrapper.AdminListProducts)
	router.POST(options.BaseURL+"/admin/products", wrapper.AdminCreateProduct)
	router.DELETE(options.BaseURL+"/admin/products/:productId", wrapper.AdminDeleteProduct)
	router.GET(options.BaseURL+"/admin/products/:productId", wrapper.AdminGetProduct)
	router.PATCH(options.BaseURL+"/admin/products/:productId", wrapper.AdminPatchProduct)
	router.PUT(options.BaseURL+"/admin/products/:productId", wrapper.AdminUpdateProduct)
	router.GET(options.BaseURL+"/admin/orders", wrapper.AdminListOrders)
	router.POST(options.BaseURL+"/admin/orders", wrapper.AdminCreateOrder)
	router.GET(options.BaseURL+"/admin/orders/pipeline", wrapper.AdminGetOrderPipeline)
	router.GET(options.BaseURL+"/admin/orders/:orderId", wrapper.AdminGetOrder)
	router.PATCH(options.BaseURL+"/admin/orders/:orderId", wrapper.AdminPatchOrder)
	router.POST(options.BaseURL+"/admin/orders/:orderId/transition", wrapper.AdminTransitionOrder)
	router.POST(options.BaseURL+"/admin/orders/:orderId/undo", wrapper.AdminUndoOrderTransition)
	router.POST(options.BaseURL+"/admin/orders/:orderId/confirm-payment", wrapper.AdminConfirmPayment)
	router.GET(options.BaseURL+"/admin/riders", wrapper.AdminListRiders)
}

